fn step(table: &[u16], state: usize, symbol: u8) -> Option<usize> {
    let mut i = state;
    while i < table.len() && table[i] != 0 {
        if (table[i] % 128) as u8 == symbol {
            return Some((table[i] / 128) as usize);
        }
        i += 1;
    }
    None
}

fn symbol(c: u8) -> u8 {
    match c {
        b'n' | b'm' => b'N',
        b'a' | b'e' | b'i' | b'o' | b'u' | b'y' => b'V',
        _ => c,
    }
}

fn walk<I: Iterator<Item = u8>>(table: &[u16], chars: I) -> bool {
    let Some(mut state) = step(table, 0, b'#') else { return false };
    for c in chars {
        let s = symbol(c);
        match step(table, state, s) {
            Some(n) => state = n,
            None => return false,
        }
        if s == b'V' {
            return true;
        }
    }
    false
}

/// True if `word` looks pronounceable, so it should be spoken rather than
/// spelled out. Expects lowercase ASCII.
pub fn is_word(word: &str) -> bool {
    let b = word.as_bytes();
    walk(&ONSET, b.iter().copied()) && walk(&CODA, b.iter().rev().copied())
}
